18	/// A stream of completion events produced by a model provider.
19	pub type CompletionStream = Pin<Box<dyn Stream<Item = Result<CompletionEvent, ModelError>> + Send>>;
20	
21	/// A model the orchestrator can call.
22	///
23	/// `stream` is the primitive. `complete` drains the stream and assembles a
24	/// `CompletionResponse`.
25	#[async_trait]
26	pub trait Model: Send + Sync {
27	    /// Human-readable name for logs and cost accounting.
28	    fn name(&self) -> &str;
29	
30	    /// Provider family, such as `anthropic`, `openai`, or `shell`.
31	    fn provider(&self) -> &str;
32	
33	    /// Cost hints used by `derrick gain`, when configured.
34	    fn cost_hint(&self) -> Option<&CostHint>;
35	
36	    /// Whether this provider delegates authentication to a host CLI.
37	    fn host_delegated_auth(&self) -> bool {
38	        false
39	    }
40	
41	    /// Streams a completion response.
42	    async fn stream(&self, request: CompletionRequest) -> Result<CompletionStream, ModelError>;
43	
44	    /// Completes a request by draining `stream`.
45	    async fn complete(&self, request: CompletionRequest) -> Result<CompletionResponse, ModelError> {
46	        let mut stream = self.stream(request).await?;
47	        let mut text = String::new();
48	        let mut tokens_in = 0;
49	        let mut tokens_out = 0;
50	        let mut finish_reason = FinishReason::Stop;
51	
52	        while let Some(event) = stream.next().await {
53	            match event? {
54	                CompletionEvent::Content { text: chunk } => text.push_str(&chunk),
55	                CompletionEvent::End {
56	                    tokens_in: input,
57	                    tokens_out: output,
58	                    finish_reason: reason,
59	                } => {
60	                    tokens_in = input;
61	                    tokens_out = output;
62	                    finish_reason = reason;
63	                }
64	            }
65	        }
66	
67	        Ok(CompletionResponse {
68	            text,
69	            tokens_in,
70	            tokens_out,
71	            finish_reason,
72	        })
73	    }
74	}
