10	const NAME: &str = "claude";
11	
12	/// Host adapter for the Claude Code CLI.
13	#[derive(Clone, Debug)]
14	pub struct ClaudeHost {
15	    binary: PathBuf,
16	}
17	
18	impl ClaudeHost {
19	    /// Creates an adapter that resolves `claude` on `PATH`.
20	    pub fn new() -> Self {
21	        Self {
22	            binary: PathBuf::from(NAME),
23	        }
24	    }
25	
26	    /// Creates an adapter using an explicit binary path.
27	    pub fn with_binary(binary: impl Into<PathBuf>) -> Self {
28	        Self {
29	            binary: binary.into(),
30	        }
31	    }
32	}
33	
34	impl Default for ClaudeHost {
35	    fn default() -> Self {
36	        Self::new()
37	    }
38	}
39	
40	/// Subset of the JSON object emitted by `claude --print --output-format json`.
41	///
42	/// Claude Code CLI (≥1.x) writes a single JSON object to stdout. We only
43	/// parse the fields we need; everything else is ignored.
44	#[derive(Deserialize)]
45	struct ClaudeJsonResult {
46	    /// The assistant's text response.
47	    #[serde(default)]
48	    result: String,
49	    /// Token usage reported by the API.
50	    #[serde(default)]
51	    usage: ClaudeUsage,
52	}
53	
54	#[derive(Default, Deserialize)]
55	struct ClaudeUsage {
56	    #[serde(default)]
57	    input_tokens: u32,
58	    #[serde(default)]
59	    output_tokens: u32,
60	}
61	
62	/// Parse `claude --output-format json` output.
63	///
64	/// Returns `(text, tokens_in, tokens_out)`. Falls back to
65	/// `(raw_stdout, 0, 0)` if the JSON is missing or malformed, so older
66	/// versions of the CLI that don't support JSON output keep working.
67	fn parse_claude_json(raw: &str) -> (String, u32, u32) {
68	    match serde_json::from_str::<ClaudeJsonResult>(raw.trim()) {
69	        Ok(parsed) => (
70	            parsed.result,
71	            parsed.usage.input_tokens,
72	            parsed.usage.output_tokens,
73	        ),
74	        Err(_) => (raw.to_owned(), 0, 0),
75	    }
76	}
77	
78	#[async_trait]
79	impl HostAdapter for ClaudeHost {
80	    fn name(&self) -> &str {
81	        NAME
82	    }
83	
84	    fn is_available(&self) -> bool {
85	        is_available(&self.binary)
86	    }
87	
88	    async fn run(&self, request: HostRequest) -> Result<HostResponse, HostError> {
89	        let mut args = vec![
90	            OsString::from("--print"),
91	            OsString::from("--output-format"),
92	            OsString::from("json"),
93	        ];
94	        if let Some(ref model) = request.model {
95	            args.push(OsString::from("--model"));
96	            args.push(OsString::from(model.as_str()));
97	        }
98	        if request.headless {
99	            // Suppress interactive permission prompts when running without a
100	            // terminal. Pipeline steps always set `HostRequest::headless = true`.
101	            args.push(OsString::from("--dangerously-skip-permissions"));
102	        }
103	        args.push(OsString::from(&request.prompt));
104	        let spec = CommandSpec {
105	            binary: self.binary.clone(),
106	            args,
107	        };
108	        let mut response = run_host(NAME, spec, request).await?;
109	        // Parse JSON to extract the text and token counts; fall back
110	        // gracefully for CLI versions that don't support --output-format json.
111	        let (text, tokens_in, tokens_out) = parse_claude_json(&response.stdout);
112	        response.stdout = text;
113	        response.tokens_in = tokens_in;
114	        response.tokens_out = tokens_out;
115	        Ok(response)
116	    }
117	}
118	
