pub(crate) struct RoleBindings {
 pub(crate) proposer: String,
 pub(crate) drafter: String,
 pub(crate) reviewer: String,
 pub(crate) executor: String,
 pub(crate) summariser: String,
}

impl RoleBindings {
 pub(crate) fn one_model(model: String) -> Self {
