fn print_plan(plan: &derrick_adopt::AdoptionPlan) {
 println!("adoption plan");
 if!plan.writes.is_empty() {
 println!("writes {}", join_planned_writes(&plan.writes));
 }
 if!plan.references.is_empty() {
 let references = plan
.references
.iter()
.map(|reference| format!("{} as {}", reference.path.display(), reference.as_field))
.collect::<Vec<_>>()
.join(", ");
 println!("references {references}");
 }
 for warning in &plan.warnings {
 println!("warning {warning}");
 }
 for blocker in &plan.blockers {
 println!("blocker {blocker}");
 }
}

fn join_planned_writes(writes: &[derrick_adopt::PlannedWrite]) -> String {
 let paths = writes
.iter()
.map(|write| write.path.clone())
.collect::<Vec<_>>();
 join_paths(&paths)
}

fn join_paths(paths: &[std::path::PathBuf]) -> String {
 paths
.iter()
.map(|path| path.display().to_string())
.collect::<Vec<_>>()
.join(", ")
}

fn ensure_git_repo(yes: bool) -> Result<std::path::PathBuf, crate::CliError> {
 let cwd = std::env::current_dir().map_err(|source| crate::CliError::Io {
 path: std::path::PathBuf::from("."),
 source,
 })?;

 eprintln!(
 "{}",
 ui::warn("No git repository found in this directory or any parent.")
 );

 let confirmed = if yes {
 true
 } else if std::io::stdin().is_terminal() {
 if ui::styled() {
 eprint!(
 " \x1b[36m›\x1b[0m Run \x1b[1mgit init\x1b[0m in {}? [Y/n] ",
 cwd.display()
 );
 } else {
 eprint!(" › Run `git init` in {}? [Y/n] ", cwd.display());
 }
 use std::io::Write as _;
 let _ = std::io::stderr().flush();
 let mut input = String::new();
 std::io::stdin()
.read_line(&mut input)
.map_err(|source| crate::CliError::Io {
 path: std::path::PathBuf::from("<stdin>"),
 source,
 })?;
!matches!(input.trim().to_ascii_lowercase().as_str(), "n" | "no")
 } else {
 false
 };

 if!confirmed {
 return Err(message("derrick init must be run inside a git repo"));
 }

 let status = std::process::Command::new("git")
.arg("init")
.current_dir(&cwd)
.status()
.map_err(|source| crate::CliError::Io {
 path: cwd.join(".git"),
 source,
 })?;

 if!status.success() {
 return Err(message("git init failed"));
 }

 println!("{}", ui::done("git repository initialised"));

 Ok(cwd)
}

