fn hand_kind_for_executor(provider: &str, cli: Option<&str>) -> HandKind {
    if provider == "copilot" || cli.is_some_and(|value| value.starts_with("copilot")) {
        HandKind::Copilot
    } else if provider == "claude" || cli.is_some_and(|value| value.starts_with("claude")) {
        HandKind::Claude
    } else {
        HandKind::Human
    }
}

